import{lessons,emptyState,freshProfiles}from'./data.js';
import {exerciseItems, makeQuestion, normalizeAnswer, trainingMenu, questionHTML, slovakVoice} from './exercises.js';
const KEY='slovicko-mvp-v1',$=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db;try{db=JSON.parse(localStorage.getItem(KEY))}catch{}if(!db||db.version!==1)db={version:1,profileId:'learner1',profiles:freshProfiles().map(p=>({...p,state:emptyState()}))};for(const p of db.profiles)p.state={...emptyState(),...p.state,stats:{...emptyState().stats,...p.state?.stats},cards:p.state?.cards||{},answers:p.state?.answers||[],learnedLessons:p.state?.learnedLessons||{},customItems:p.state?.customItems||[]};if(!db.profiles.length)db.profiles=freshProfiles().map(p=>({...p,state:emptyState()}));
let view=['today','lessons','practice','dictionary'].includes(location.hash.slice(1))?location.hash.slice(1):'today',opened=null,filter='Все',session=null,timer;
const who=()=>db.profiles.find(p=>p.id===db.profileId)||db.profiles[0],state=()=>who().state,all=()=>[...lessons.flatMap(l=>l.items),...exerciseItems,...db.profiles.flatMap(p=>p.state.customItems)],unique=()=>[...new Map([...all()].reverse().map(i=>[i.sk.toLowerCase(),i])).values()];
const dateKey=(d=new Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;function plural(n,a,b,c){let x=n%10,y=n%100;return x===1&&y!==11?a:x>=2&&x<=4&&(y<12||y>14)?b:c}const learned=()=>new Set([...Object.keys(state().cards).filter(k=>state().cards[k].seen),...state().customItems.map(i=>i.sk)]),card=i=>state().cards[i.sk]||{box:0,due:null,seen:0,correct:0,wrong:0,favorite:false},due=()=>unique().filter(i=>learned().has(i.sk)&&card(i).due&&card(i).due<=dateKey());
function header(){const s=state();$('#profileEmoji').textContent=who().emoji;$('#profileSelect').innerHTML=db.profiles.map(p=>`<option value="${esc(p.id)}"${p.id===who().id?' selected':''}>${esc(p.name)}</option>`).join('');$('#streakChip').innerHTML=`<span>♨</span> <b>${s.stats.streak}</b> дн.`;$('#xpChip').innerHTML=`<span>✦</span> <b>${s.stats.xp}</b> XP`;$('#reviewBadge').textContent=due().length||''}function save(){localStorage.setItem(KEY,JSON.stringify(db));header()}function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>t.classList.remove('show'),2000)}function navigate(v){window.speechSynthesis?.cancel();view=v;opened=null;session=null;history.replaceState(null,'',`#${v}`);render();scrollTo(0,0)}function typeName(i){return i.type==='phrase'?'фраза':i.type==='grammar'?'правило':'слово'}
function today(){const n=due().length,s=state(),count=learned().size,total=unique().length;return `<div class="welcome-row"><div><p class="eyebrow">${new Intl.DateTimeFormat('ru',{day:'numeric',month:'long'}).format(new Date()).toLocaleUpperCase('ru')}</p><h1>С возвращением, <span>${esc(who().name)}!</span></h1><p class="welcome-note">Учим словацкий понемногу — и не забываем пройденное.</p></div><button class="outline-button" data-action="rename">✎ Имя</button></div><section class="hero-card"><div class="hero-copy"><span class="hero-label">ВАШ СЛОВАЦКИЙ · ВАШ РИТМ</span><h2>${n?`Повторим ${n} ${plural(n,'карточку','карточки','карточек')}`:'Каждый день — маленький шаг'}</h2><p>${n?'Знакомые слова возвращаются как раз вовремя. Начните с короткой тренировки.':'Выберите урок, чтобы познакомиться со словами и начать свою историю повторений.'}</p><button class="primary-button" data-action="start-review">${n?'Начать повторение':'Начать уроки'}　→</button></div><div class="hero-illustration" aria-hidden="true"><div class="hero-sun"></div><div class="hero-book"></div><span class="hero-spark">✳</span><span class="hero-star">✦</span></div></section><section class="stats-grid"><article class="stat-card"><span class="stat-icon">▤</span><div><div class="stat-value">${count}</div><div class="stat-label">слов в вашем прогрессе</div></div></article><article class="stat-card"><span class="stat-icon">♨</span><div><div class="stat-value">${s.stats.streak} ${plural(s.stats.streak,'день','дня','дней')}</div><div class="stat-label">серия занятий</div></div></article><article class="stat-card"><span class="stat-icon">✦</span><div><div class="stat-value">${s.stats.xp} XP</div><div class="stat-label">заработано очков</div></div></article></section><div class="home-grid"><section class="panel review-panel"><div class="panel-top"><span class="panel-title">Пора освежить в памяти</span><span class="tiny-pill">${n} к повторению</span></div><div class="review-content"><p>${n?`На сегодня готовы ${due().slice(0,3).map(i=>esc(i.sk)).join(' · ')}.`:'После первого упражнения здесь появятся карточки для повторения.'}</p><button class="soft-button" data-action="start-review">${n?'Повторить →':'К урокам →'}</button></div></section><section class="panel progress-panel"><div class="panel-top"><span class="panel-title">Ваши первые слова</span><span class="tiny-pill">${Math.round(count/total*100)}%</span></div><div class="progress-heading"><span>Начали учить</span><strong>${count} из ${total}</strong></div><div class="progress-track"><div class="progress-fill" style="width:${count/total*100}%"></div></div><div class="progress-foot"><span>Пройдено уроков</span><b>${Object.keys(s.learnedLessons).length} / ${lessons.length}</b></div></section></div><div class="section-head"><div><p class="section-kicker">ПУТЕШЕСТВИЕ НАЧИНАЕТСЯ</p><h2>Первые уроки</h2></div><a data-view="lessons">Все уроки →</a></div><div class="lesson-mini-list">${lessons.slice(0,3).map(l=>`<article class="lesson-mini" data-lesson="${l.id}"><span class="lesson-completed">${s.learnedLessons[l.id]?'✓':''}</span><span class="lesson-mini-emoji">${l.emoji}</span><h3>${esc(l.title)}</h3><p>${l.items.length} карточек · ${s.learnedLessons[l.id]?'пройдено':'начать'}</p></article>`).join('')}</div>`}
function lessonPage(){if(opened){let l=lessons.find(x=>x.id===opened);return `<div class="lesson-detail"><button class="back-button" data-action="back">←　Все уроки</button><div class="lesson-detail-hero"><span class="lesson-detail-emoji">${l.emoji}</span><h2>${esc(l.title)}</h2><p>${esc(l.description)}</p><div class="lesson-detail-info"><span class="tiny-pill">${l.items.length} карточек</span><span class="tiny-pill">${state().learnedLessons[l.id]?'✓ пройдено':'прогресс сохранится'}</span><button class="primary-button" style="margin-left:auto" data-action="lesson-start" data-id="${l.id}">Практиковать урок →</button></div></div><div class="content-list">${l.items.map(i=>`<article class="content-row"><span class="sk">${esc(i.sk)}</span><span class="ru">${esc(i.ru)}</span><span class="type">${typeName(i)}</span></article>`).join('')}</div></div>`}return `<div class="page-heading"><div><p class="eyebrow">ЛЮБОЙ УРОК ВСЕГДА РЯДОМ</p><h1>Ваши уроки</h1><p>Возвращайтесь к знакомому материалу в удобное время.</p></div><span class="tiny-pill">${lessons.length} уроков</span></div><div class="lesson-list">${lessons.map((l,n)=>`<article class="lesson-card" data-lesson="${l.id}"><div class="lesson-emoji">${l.emoji}</div><div><div class="lesson-title-row"><h3>${String(n+1).padStart(2,'0')}. ${esc(l.title)}</h3>${state().learnedLessons[l.id]?'<span class="done-pill">✓ пройден</span>':''}</div><p class="lesson-desc">${esc(l.description)}</p></div><div class="lesson-meta"><strong>${l.items.length} карточек</strong><span class="arrow">→</span></div></article>`).join('')}</div>`}
function start(items,kind='lesson',lessonId=null,mode='mixed',limit=null){
 if(!items.length){toast('Пока нет карточек для повторения.');return}
 const shuffled=[...items];for(let j=shuffled.length-1;j>0;j--){const k=Math.floor(Math.random()*(j+1));[shuffled[j],shuffled[k]]=[shuffled[k],shuffled[j]]}
 session={items:limit?shuffled.slice(0,limit):shuffled,index:0,answered:false,correct:0,xp:0,kind,lessonId,mode};view='practice';opened=null;render();scrollTo(0,0);
}
function practice(){
 if(!session)return trainingMenu(lessons,due().length);
 if(session.index>=session.items.length)return `<div class="practice-shell"><section class="empty-state"><div class="empty-state-icon">🎉</div><h3>Тренировка завершена</h3><p>Правильных ответов: ${session.correct} из ${session.items.length}. Заработано ${session.xp} XP. Ошибки сохранены для повторения.</p><button class="primary-button" data-action="done">Готово →</button></section></div>`;
 const i=session.items[session.index];if(!session.question)session.question=makeQuestion(i,session.mode,session.index,unique());
 return questionHTML(session,esc);
}
function vocabItem(i){const c=card(i);return `<div class="vocab-row"><div class="vocab-copy"><div class="vocab-sk">${esc(i.sk)}</div><div class="vocab-ru">${esc(i.ru)}</div></div><span class="vocab-tag">${typeName(i)}</span><button class="vocab-voice" data-speak="${esc(i.sk)}" aria-label="Озвучить по-словацки" ${slovakVoice()?'':'hidden'}>◖))</button><button class="star-button ${c.favorite?'known':''}" data-favorite="${esc(i.sk)}">${c.favorite?'★':'☆'}</button></div>`}function dictionary(){const q=$('#dictionarySearch')?.value||'',items=unique().filter(i=>!i.exercise).filter(i=>filter==='Все'||filter==='Слова'&&i.type==='word'||filter==='Фразы'&&i.type==='phrase'||filter==='Правила'&&i.type==='grammar'||filter==='Мои слова'&&i.custom).filter(i=>`${i.sk} ${i.ru} ${i.lessonTitle||''}`.toLowerCase().includes(q.toLowerCase()));return `<div class="page-heading"><div><p class="eyebrow">ВСЁ ПРОЙДЕННОЕ — ПОД РУКОЙ</p><h1>Словарь</h1><p>Ищите слова и добавляйте собственные карточки.</p></div><button class="primary-button" data-action="add-word">＋ Добавить слово</button></div><div class="dictionary-tools"><label class="search-wrap"><span class="search-icon">⌕</span><input id="dictionarySearch" class="search-input" type="search" placeholder="Поиск на словацком или русском…" value="${esc(q)}"></label></div><div class="filter-tabs">${['Все','Слова','Фразы','Правила','Мои слова'].map(x=>`<button class="filter-tab ${filter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div><p class="word-count">${items.length} ${plural(items.length,'карточка','карточки','карточек')}</p>${items.length?`<div class="vocab-list">${items.map(vocabItem).join('')}</div>`:'<div class="no-results">Ничего не найдено.</div>'}`}
function render(){header();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#screen').innerHTML=view==='today'?today():view==='lessons'?lessonPage():view==='practice'?practice():dictionary();if(session&&!session.answered)$('#writtenAnswer')?.focus()}
function reply(answer){if(!session||session.answered)return;const i=session.items[session.index],q=session.question,ok=q.mode==='choice'?i.sk===answer:q.answers.some(x=>normalizeAnswer(x)===normalizeAnswer(answer)),c=state().cards[i.sk]||(state().cards[i.sk]={box:0,due:null,seen:0,correct:0,wrong:0,favorite:false});session.answered=true;session.selected=answer;session.ok=ok;session.correct+=Number(ok);c.seen++;if(ok){c.correct++;c.box=Math.min(6,c.box+1);const d=new Date;d.setDate(d.getDate()+[1,3,7,14,30,60][c.box-1]);c.due=dateKey(d);session.xp+=10;state().stats.xp+=10}else{c.wrong++;c.box=0;const d=new Date;d.setDate(d.getDate()+1);c.due=dateKey(d);session.xp+=2;state().stats.xp+=2}state().answers.push({sk:i.sk,correct:ok,date:dateKey(),answer,mode:q.mode});state().answers=state().answers.slice(-500);const now=dateKey();if(state().stats.lastStudy!==now){const y=new Date;y.setDate(y.getDate()-1);state().stats.streak=state().stats.lastStudy===dateKey(y)?state().stats.streak+1:1;state().stats.lastStudy=now}save();render()}
function modal(kind){const root=$('#modal');root.hidden=false;root.innerHTML=kind==='word'?`<form class="modal" id="addWordForm"><div class="modal-top"><div><h2>Добавить слово</h2><p class="modal-subtitle">Личная карточка появится в словаре и расписании после практики.</p></div><button type="button" class="modal-close" data-action="close">×</button></div><label class="field-label" for="newSk">На словацком</label><input class="field-input" id="newSk" maxlength="100" required placeholder="napríklad: dobrý deň"><label class="field-label" for="newRu">Перевод</label><input class="field-input" id="newRu" maxlength="150" required placeholder="например: добрый день"><label class="field-label" for="newType">Тип</label><select class="field-select" id="newType"><option value="word">Слово</option><option value="phrase">Фраза</option><option value="grammar">Правило</option></select><div class="modal-actions"><button type="button" class="quiet-button" data-action="close">Отмена</button><button class="primary-button">Сохранить</button></div></form>`:`<form class="modal" id="renameForm"><div class="modal-top"><div><h2>Имя профиля</h2><p class="modal-subtitle">Прогресс у каждого профиля отдельный.</p></div><button type="button" class="modal-close" data-action="close">×</button></div><label class="field-label" for="profileNameInput">Как к вам обращаться?</label><input class="field-input" id="profileNameInput" required maxlength="28" value="${esc(who().name)}"><div class="modal-actions"><button type="button" class="quiet-button" data-action="close">Отмена</button><button class="primary-button">Сохранить</button></div></form>`;root.querySelector('input')?.focus()}
document.addEventListener('click',e=>{
 const train=e.target.closest('[data-train]');if(train){const mode=train.dataset.train,topic=$('#practiceTopic')?.value||'all';let items=topic==='all'?unique().filter(i=>!i.exercise):lessons.find(l=>l.id===topic).items;if(mode==='grammar')items=exerciseItems.filter(i=>i.exercise==='gap');if(mode==='pronouns')items=exerciseItems.filter(i=>i.exercise==='pronoun');if(mode==='situation')items=exerciseItems.filter(i=>i.exercise==='situation');start(items,'training',null,mode,mode==='grammar'?null:10);return}
 const char=e.target.closest('[data-char]');if(char){const input=$('#writtenAnswer');if(input&&!input.disabled){const a=input.selectionStart,b=input.selectionEnd;input.setRangeText(char.dataset.char,a,b,'end');input.focus()}return}
const nav=e.target.closest('[data-view]');if(nav){navigate(nav.dataset.view);return}const l=e.target.closest('[data-lesson]');if(l){opened=l.dataset.lesson;view='lessons';render();return}const lp=e.target.closest('[data-lesson-practice]');if(lp){const lesson=lessons.find(x=>x.id===lp.dataset.lessonPractice);start(lesson.items.filter(i=>learned().has(i.sk)));return}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render();return}const fav=e.target.closest('[data-favorite]');if(fav){const i=unique().find(x=>x.sk===fav.dataset.favorite),c=state().cards[i.sk]||(state().cards[i.sk]={...card(i)});c.favorite=!c.favorite;save();render();return}const speech=e.target.closest('[data-speak]');if(speech){const voice=slovakVoice();if(voice){const u=new SpeechSynthesisUtterance(speech.dataset.speak);u.voice=voice;u.lang=voice.lang;u.rate=.85;speechSynthesis.cancel();speechSynthesis.speak(u)}else toast('Словацкий голос недоступен на этом устройстве.');return}const a=e.target.closest('[data-answer]');if(a){reply(a.dataset.answer);return}const b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case'start-review':if(!due().length&&view==='today')navigate('lessons');else start(due(),'review');break;case'lesson-start':{const x=lessons.find(y=>y.id===b.dataset.id);start(x.id==='byt'?exerciseItems.filter(i=>i.lessonId==='byt'):x.id==='pronouns'?[...x.items,...exerciseItems.filter(i=>i.exercise==='pronoun')]:x.items,'lesson',x.id);break}case'next':session.index++;if(session.index===session.items.length&&session.lessonId){state().learnedLessons[session.lessonId]=true;save()}session.answered=false;session.question=null;render();break;case'done':if(session.lessonId)state().learnedLessons[session.lessonId]=true;save();session=null;navigate('today');break;case'quit':session=null;render();break;case'back':opened=null;render();break;case'add-word':modal('word');break;case'rename':modal('name');break;case'close':$('#modal').hidden=true;break}});
document.addEventListener('change',e=>{if(e.target.id==='profileSelect'){window.speechSynthesis?.cancel();db.profileId=e.target.value;session=null;opened=null;save();render()}});document.addEventListener('input',e=>{if(e.target.id!=='dictionarySearch')return;const q=e.target.value,pos=e.target.selectionStart,items=unique().filter(i=>!i.exercise).filter(i=>filter==='Все'||filter==='Слова'&&i.type==='word'||filter==='Фразы'&&i.type==='phrase'||filter==='Правила'&&i.type==='grammar'||filter==='Мои слова'&&i.custom).filter(i=>`${i.sk} ${i.ru} ${i.lessonTitle||''}`.toLowerCase().includes(q.toLowerCase())),old=$('.vocab-list'),empty=$('.no-results'),count=$('.word-count');if(count)count.textContent=`${items.length} ${plural(items.length,'карточка','карточки','карточек')}`;const html=items.length?`<div class="vocab-list">${items.map(vocabItem).join('')}</div>`:'<div class="no-results">Ничего не найдено.</div>';if(old)old.outerHTML=html;else if(empty)empty.outerHTML=html;});
document.addEventListener('submit',e=>{if(e.target.id==='answerForm'){e.preventDefault();const value=$('#writtenAnswer').value.trim();if(value)reply(value);return}if(e.target.id==='addWordForm'){e.preventDefault();const sk=$('#newSk').value.trim(),ru=$('#newRu').value.trim();if(unique().some(i=>i.sk.toLowerCase()===sk.toLowerCase()))return toast('Это слово уже есть в словаре');state().customItems.push({sk,ru,type:$('#newType').value,lessonId:'custom',lessonTitle:'Мои слова',custom:true});save();$('#modal').hidden=true;filter='Мои слова';render();toast('Слово добавлено в словарь')}if(e.target.id==='renameForm'){e.preventDefault();who().name=$('#profileNameInput').value.trim();save();$('#modal').hidden=true;render();toast('Имя профиля обновлено')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').hidden){$('#modal').hidden=true;return}if(e.target.matches('input,textarea,select'))return;if(view==='practice'&&session&&!session.answered&&/^[1-4]$/.test(e.key))document.querySelectorAll('[data-answer]')[+e.key-1]?.click();else if(view==='practice'&&session?.answered&&e.key==='Enter')document.querySelector('[data-action="next"]')?.click()});if(window.speechSynthesis)speechSynthesis.addEventListener('voiceschanged',()=>{document.querySelectorAll('[data-speak]').forEach(b=>b.hidden=!slovakVoice())});window.addEventListener('hashchange',()=>{if(['today','lessons','practice','dictionary'].includes(location.hash.slice(1))){view=location.hash.slice(1);opened=null;session=null;render()}});render();
